package store.cadera.cdrjobs.data;

import org.bukkit.Location;
import store.cadera.cdrjobs.model.*;

import java.io.File;
import java.sql.*;
import java.util.*;

public final class Database implements AutoCloseable {
    private final String url;
    private Connection connection;
    public Database(File dataFolder){if(!dataFolder.exists()&&!dataFolder.mkdirs())throw new IllegalStateException("Could not create plugin data folder");url="jdbc:sqlite:"+new File(dataFolder,"cdrjobs.db").getAbsolutePath();}
    public void connect()throws SQLException{try{Class.forName("org.sqlite.JDBC");}catch(ClassNotFoundException e){throw new SQLException("SQLite JDBC driver not found",e);}connection=DriverManager.getConnection(url);try(Statement s=connection.createStatement()){s.execute("PRAGMA journal_mode=WAL");s.execute("PRAGMA synchronous=NORMAL");s.execute("CREATE TABLE IF NOT EXISTS player_profile (uuid TEXT PRIMARY KEY, fate_essence INTEGER NOT NULL DEFAULT 0)");s.execute("CREATE TABLE IF NOT EXISTS job_progress (uuid TEXT NOT NULL, job TEXT NOT NULL, level INTEGER NOT NULL DEFAULT 1, xp INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(uuid, job))");s.execute("CREATE TABLE IF NOT EXISTS player_skills (uuid TEXT NOT NULL, skill TEXT NOT NULL, rank INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(uuid, skill))");s.execute("CREATE TABLE IF NOT EXISTS placed_ores (world TEXT NOT NULL, x INTEGER NOT NULL, y INTEGER NOT NULL, z INTEGER NOT NULL, PRIMARY KEY(world, x, y, z))");s.execute("CREATE TABLE IF NOT EXISTS miner_trials (uuid TEXT PRIMARY KEY, total_ores INTEGER NOT NULL DEFAULT 0, deep_ores INTEGER NOT NULL DEFAULT 0, rare_ores INTEGER NOT NULL DEFAULT 0, ancient_debris INTEGER NOT NULL DEFAULT 0, stone_complete INTEGER NOT NULL DEFAULT 0, deep_complete INTEGER NOT NULL DEFAULT 0)");s.execute("CREATE TABLE IF NOT EXISTS ability_cooldowns (uuid TEXT NOT NULL, ability TEXT NOT NULL, ready_at INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(uuid, ability))");s.execute("CREATE TABLE IF NOT EXISTS fate_milestone_claims (uuid TEXT NOT NULL, job TEXT NOT NULL, milestone INTEGER NOT NULL, PRIMARY KEY(uuid, job, milestone))");}}
    private void ensureProfile(UUID u)throws SQLException{try(PreparedStatement p=connection.prepareStatement("INSERT OR IGNORE INTO player_profile(uuid,fate_essence) VALUES(?,0)")){p.setString(1,u.toString());p.executeUpdate();}}
    private void ensureJob(UUID u,JobType j)throws SQLException{try(PreparedStatement p=connection.prepareStatement("INSERT OR IGNORE INTO job_progress(uuid,job,level,xp) VALUES(?,?,1,0)")){p.setString(1,u.toString());p.setString(2,j.name());p.executeUpdate();}}
    private void ensureMinerTrial(UUID u)throws SQLException{try(PreparedStatement p=connection.prepareStatement("INSERT OR IGNORE INTO miner_trials(uuid) VALUES(?)")){p.setString(1,u.toString());p.executeUpdate();}}
    public synchronized JobProgress getProgress(UUID u,JobType j){try{ensureJob(u,j);try(PreparedStatement p=connection.prepareStatement("SELECT level,xp FROM job_progress WHERE uuid=? AND job=?")){p.setString(1,u.toString());p.setString(2,j.name());try(ResultSet r=p.executeQuery()){if(r.next())return new JobProgress(r.getInt(1),r.getLong(2));}}}catch(SQLException e){throw new IllegalStateException("Failed to read progress",e);}return new JobProgress(1,0);}
    public synchronized void setProgress(UUID u,JobType j,int level,long xp){try{ensureJob(u,j);try(PreparedStatement p=connection.prepareStatement("UPDATE job_progress SET level=?,xp=? WHERE uuid=? AND job=?")){p.setInt(1,level);p.setLong(2,xp);p.setString(3,u.toString());p.setString(4,j.name());p.executeUpdate();}}catch(SQLException e){throw new IllegalStateException("Failed to save progress",e);}}
    public synchronized int getFateEssence(UUID u){try{ensureProfile(u);try(PreparedStatement p=connection.prepareStatement("SELECT fate_essence FROM player_profile WHERE uuid=?")){p.setString(1,u.toString());try(ResultSet r=p.executeQuery()){return r.next()?r.getInt(1):0;}}}catch(SQLException e){throw new IllegalStateException("Failed to read Fate Essence",e);}}
    public synchronized void addFateEssence(UUID u,int a){try{ensureProfile(u);try(PreparedStatement p=connection.prepareStatement("UPDATE player_profile SET fate_essence=MAX(0,fate_essence+?) WHERE uuid=?")){p.setInt(1,a);p.setString(2,u.toString());p.executeUpdate();}}catch(SQLException e){throw new IllegalStateException("Failed to update Fate Essence",e);}}
    public synchronized void setFateEssence(UUID u,int a){try{ensureProfile(u);try(PreparedStatement p=connection.prepareStatement("UPDATE player_profile SET fate_essence=? WHERE uuid=?")){p.setInt(1,Math.max(0,a));p.setString(2,u.toString());p.executeUpdate();}}catch(SQLException e){throw new IllegalStateException("Failed to set Fate Essence",e);}}
    public synchronized boolean claimFateMilestoneReward(UUID u,JobType j,int milestone,int amount){try{ensureProfile(u);connection.setAutoCommit(false);try(PreparedStatement c=connection.prepareStatement("INSERT OR IGNORE INTO fate_milestone_claims(uuid,job,milestone) VALUES(?,?,?)");PreparedStatement r=connection.prepareStatement("UPDATE player_profile SET fate_essence=fate_essence+? WHERE uuid=?")){c.setString(1,u.toString());c.setString(2,j.name());c.setInt(3,milestone);boolean fresh=c.executeUpdate()>0;if(fresh){r.setInt(1,Math.max(0,amount));r.setString(2,u.toString());r.executeUpdate();}connection.commit();return fresh;}catch(SQLException e){connection.rollback();throw e;}finally{connection.setAutoCommit(true);}}catch(SQLException e){throw new IllegalStateException("Failed to claim Fate Essence milestone",e);}}
    public synchronized void backfillFateMilestoneClaims(Collection<Integer> milestones){if(milestones==null||milestones.isEmpty())return;List<ProgressSeed> rows=new ArrayList<>();try(PreparedStatement p=connection.prepareStatement("SELECT uuid,job,level FROM job_progress");ResultSet r=p.executeQuery()){while(r.next())rows.add(new ProgressSeed(r.getString(1),r.getString(2),r.getInt(3)));}catch(SQLException e){throw new IllegalStateException("Failed to inspect progression for Fate migration",e);}try{connection.setAutoCommit(false);try(PreparedStatement p=connection.prepareStatement("INSERT OR IGNORE INTO fate_milestone_claims(uuid,job,milestone) VALUES(?,?,?)")){for(ProgressSeed row:rows)for(int m:milestones)if(m<=row.level()){p.setString(1,row.uuid());p.setString(2,row.job());p.setInt(3,m);p.addBatch();}p.executeBatch();connection.commit();}catch(SQLException e){connection.rollback();throw e;}finally{connection.setAutoCommit(true);}}catch(SQLException e){throw new IllegalStateException("Failed to migrate Fate milestone claims",e);}}
    public synchronized int getSkillRank(UUID u,MinerSkill s){try(PreparedStatement p=connection.prepareStatement("SELECT rank FROM player_skills WHERE uuid=? AND skill=?")){p.setString(1,u.toString());p.setString(2,s.name());try(ResultSet r=p.executeQuery()){return r.next()?r.getInt(1):0;}}catch(SQLException e){throw new IllegalStateException("Failed to read skill rank",e);}}
    public synchronized void setSkillRank(UUID u,MinerSkill s,int rank){try(PreparedStatement p=connection.prepareStatement("INSERT INTO player_skills(uuid,skill,rank) VALUES(?,?,?) ON CONFLICT(uuid,skill) DO UPDATE SET rank=excluded.rank")){p.setString(1,u.toString());p.setString(2,s.name());p.setInt(3,rank);p.executeUpdate();}catch(SQLException e){throw new IllegalStateException("Failed to save skill",e);}}
    public synchronized Map<String,Integer> getSkillRanks(UUID u){Map<String,Integer> out=new LinkedHashMap<>();try(PreparedStatement p=connection.prepareStatement("SELECT skill,rank FROM player_skills WHERE uuid=? ORDER BY skill")){p.setString(1,u.toString());try(ResultSet r=p.executeQuery()){while(r.next())out.put(r.getString(1),r.getInt(2));}}catch(SQLException e){throw new IllegalStateException("Failed to inspect skills",e);}return out;}
    public synchronized MinerTrialProgress getMinerTrialProgress(UUID u){try{ensureMinerTrial(u);try(PreparedStatement p=connection.prepareStatement("SELECT total_ores,deep_ores,rare_ores,ancient_debris,stone_complete,deep_complete FROM miner_trials WHERE uuid=?")){p.setString(1,u.toString());try(ResultSet r=p.executeQuery()){if(r.next())return new MinerTrialProgress(r.getInt(1),r.getInt(2),r.getInt(3),r.getInt(4),r.getInt(5)!=0,r.getInt(6)!=0);}}}catch(SQLException e){throw new IllegalStateException("Failed to read Miner trial progress",e);}return new MinerTrialProgress(0,0,0,0,false,false);}
    public synchronized MinerTrialProgress incrementMinerTrial(UUID u,boolean deep,boolean rare,boolean ancient){try{ensureMinerTrial(u);try(PreparedStatement p=connection.prepareStatement("UPDATE miner_trials SET total_ores=total_ores+1,deep_ores=deep_ores+?,rare_ores=rare_ores+?,ancient_debris=ancient_debris+? WHERE uuid=?")){p.setInt(1,deep?1:0);p.setInt(2,rare?1:0);p.setInt(3,ancient?1:0);p.setString(4,u.toString());p.executeUpdate();}return getMinerTrialProgress(u);}catch(SQLException e){throw new IllegalStateException("Failed to update Miner trial progress",e);}}
    public synchronized void setStoneTrialComplete(UUID u){setTrialFlag(u,"stone_complete");}public synchronized void setDeepTrialComplete(UUID u){setTrialFlag(u,"deep_complete");}
    private void setTrialFlag(UUID u,String col){if(!col.equals("stone_complete")&&!col.equals("deep_complete"))throw new IllegalArgumentException("Invalid trial flag");try{ensureMinerTrial(u);try(PreparedStatement p=connection.prepareStatement("UPDATE miner_trials SET "+col+"=1 WHERE uuid=?")){p.setString(1,u.toString());p.executeUpdate();}}catch(SQLException e){throw new IllegalStateException("Failed to complete Miner trial",e);}}
    public synchronized void resetMinerTrial(UUID u){try(PreparedStatement p=connection.prepareStatement("DELETE FROM miner_trials WHERE uuid=?")){p.setString(1,u.toString());p.executeUpdate();}catch(SQLException e){throw new IllegalStateException("Failed to reset Miner trials",e);}}
    public synchronized long getAbilityReadyAt(UUID u,String a){try(PreparedStatement p=connection.prepareStatement("SELECT ready_at FROM ability_cooldowns WHERE uuid=? AND ability=?")){p.setString(1,u.toString());p.setString(2,a);try(ResultSet r=p.executeQuery()){return r.next()?r.getLong(1):0L;}}catch(SQLException e){throw new IllegalStateException("Failed to read ability cooldown",e);}}
    public synchronized void setAbilityReadyAt(UUID u,String a,long at){try(PreparedStatement p=connection.prepareStatement("INSERT INTO ability_cooldowns(uuid,ability,ready_at) VALUES(?,?,?) ON CONFLICT(uuid,ability) DO UPDATE SET ready_at=excluded.ready_at")){p.setString(1,u.toString());p.setString(2,a);p.setLong(3,at);p.executeUpdate();}catch(SQLException e){throw new IllegalStateException("Failed to save ability cooldown",e);}}
    public synchronized Map<String,Long> getAbilityCooldowns(UUID u){Map<String,Long> out=new LinkedHashMap<>();try(PreparedStatement p=connection.prepareStatement("SELECT ability,ready_at FROM ability_cooldowns WHERE uuid=? ORDER BY ability")){p.setString(1,u.toString());try(ResultSet r=p.executeQuery()){while(r.next())out.put(r.getString(1),r.getLong(2));}}catch(SQLException e){throw new IllegalStateException("Failed to inspect cooldowns",e);}return out;}
    public synchronized void clearAbilityCooldowns(UUID u,JobType j){String pattern=j==JobType.MINER?"runic_%":j.name().toLowerCase(Locale.ROOT)+"_%";try(PreparedStatement p=connection.prepareStatement("DELETE FROM ability_cooldowns WHERE uuid=? AND ability LIKE ?")){p.setString(1,u.toString());p.setString(2,pattern);p.executeUpdate();}catch(SQLException e){throw new IllegalStateException("Failed to reset ability cooldowns",e);}}
    public synchronized void resetProfession(UUID u,JobType j){try{connection.setAutoCommit(false);String id=u.toString();try(PreparedStatement p=connection.prepareStatement("DELETE FROM job_progress WHERE uuid=? AND job=?")){p.setString(1,id);p.setString(2,j.name());p.executeUpdate();}if(j==JobType.MINER){try(PreparedStatement s=connection.prepareStatement("DELETE FROM player_skills WHERE uuid=? AND skill NOT LIKE 'FARMER_%' AND skill NOT LIKE 'HUNTER_%' AND skill NOT LIKE 'LUMBERJACK_%' AND skill NOT LIKE 'FISHER_%'");PreparedStatement t=connection.prepareStatement("DELETE FROM miner_trials WHERE uuid=?")){s.setString(1,id);s.executeUpdate();t.setString(1,id);t.executeUpdate();}}else{try(PreparedStatement s=connection.prepareStatement("DELETE FROM player_skills WHERE uuid=? AND skill LIKE ?")){s.setString(1,id);s.setString(2,j.name()+"_%");s.executeUpdate();}}String pattern=j==JobType.MINER?"runic_%":j.name().toLowerCase(Locale.ROOT)+"_%";try(PreparedStatement c=connection.prepareStatement("DELETE FROM ability_cooldowns WHERE uuid=? AND ability LIKE ?")){c.setString(1,id);c.setString(2,pattern);c.executeUpdate();}connection.commit();}catch(SQLException e){try{connection.rollback();}catch(SQLException ignored){}throw new IllegalStateException("Failed to reset profession",e);}finally{try{connection.setAutoCommit(true);}catch(SQLException ignored){}}}
    public synchronized void resetPlayer(UUID u){try{connection.setAutoCommit(false);String id=u.toString();String[] sql={"DELETE FROM player_profile WHERE uuid=?","DELETE FROM job_progress WHERE uuid=?","DELETE FROM player_skills WHERE uuid=?","DELETE FROM miner_trials WHERE uuid=?","DELETE FROM ability_cooldowns WHERE uuid=?","DELETE FROM fate_milestone_claims WHERE uuid=?"};for(String q:sql)try(PreparedStatement p=connection.prepareStatement(q)){p.setString(1,id);p.executeUpdate();}connection.commit();}catch(SQLException e){try{connection.rollback();}catch(SQLException ignored){}throw new IllegalStateException("Failed to reset player",e);}finally{try{connection.setAutoCommit(true);}catch(SQLException ignored){}}}
    public synchronized void markPlacedOre(Location l){try(PreparedStatement p=connection.prepareStatement("INSERT OR IGNORE INTO placed_ores(world,x,y,z) VALUES(?,?,?,?)")){p.setString(1,l.getWorld().getUID().toString());p.setInt(2,l.getBlockX());p.setInt(3,l.getBlockY());p.setInt(4,l.getBlockZ());p.executeUpdate();}catch(SQLException e){throw new IllegalStateException("Failed to track placed ore",e);}}
    public synchronized boolean isPlacedOre(Location l){try(PreparedStatement p=connection.prepareStatement("SELECT 1 FROM placed_ores WHERE world=? AND x=? AND y=? AND z=? LIMIT 1")){p.setString(1,l.getWorld().getUID().toString());p.setInt(2,l.getBlockX());p.setInt(3,l.getBlockY());p.setInt(4,l.getBlockZ());try(ResultSet r=p.executeQuery()){return r.next();}}catch(SQLException e){throw new IllegalStateException("Failed to inspect placed ore",e);}}
    public synchronized boolean consumePlacedOre(Location l){try(PreparedStatement p=connection.prepareStatement("DELETE FROM placed_ores WHERE world=? AND x=? AND y=? AND z=?")){p.setString(1,l.getWorld().getUID().toString());p.setInt(2,l.getBlockX());p.setInt(3,l.getBlockY());p.setInt(4,l.getBlockZ());return p.executeUpdate()>0;}catch(SQLException e){throw new IllegalStateException("Failed to check placed ore",e);}}
    @Override public void close()throws SQLException{if(connection!=null&&!connection.isClosed())connection.close();}
    private record ProgressSeed(String uuid,String job,int level){}
}
